    (* [comment removed for export] *)
    Lemma failt_fin : forall (pc0 : Z) msF mo mc (r : rv) Fx fcx pad mw bw ew xg ng j6 f0 (q ev loc : Z),
      (pc0 = 0xfc52c /\ rs1 r = Z_to_bv 64 q) \/ (pc0 = 0xfc530 /\ ra0 r = a0 /\ rs1 r = Z_to_bv 64 q) \/ (pc0 = 0xfc534 /\ ra0 r = a0 /\ ra1 r = Z_to_bv 64 q) ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 pc0) fcx None mc (seg_rom asegs) -> frm0 fcx ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) ->
      uframe mc spw pad mw bw ew xg ng j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> ra2 r = Z_to_bv 64 ev -> ra3 r = Z_to_bv 64 loc ->
      p <= q <= e -> 1 <= ev < 1000 -> 2 <= loc < 2^32 ->
