    (* [comment removed for export] *)
    Ltac disj LV := try (destruct LV as [LV|LV]; [| disj LV]).
    Ltac leaf_open P1 :=
      let pc1 := fresh "pc1" in let LV := fresh "LV" in
      destruct P1 as (pc1 & ?r1 & ?m1 & ?E1 & LV); disj LV; splits LV; subst pc1; leaf_regs r1.
    Ltac nsx NS ST INB SHB :=
      first [ match goal with Hm : munch ?W ?mc ?m1, Hw : wmono _ ?mc ?m1, Hi : mem_inv _ ?m1 |- _ =>
                let SUB := fresh "SUB" in
                assert (SUB : sub_fp W [(bv_unsigned sp - 96, bv_unsigned sp)]%Z) by (first [apply sub_96; lia | apply sub_nil]);
                pose proof (nst_frame mc m1 W NS Hm (sub_lo W SUB) Hw Hi) as NSx; pose proof (stk_frame mc m1 W ST Hm SUB Hw) as STx;
                pose proof (pinb_frame mc m1 W INB Hm (sub_lo W SUB)) as INBx; pose proof (pshb_frame mc m1 W SHB Hm (sub_lo W SUB)) as SHBx
              end
            | pose proof NS as NSx; pose proof ST as STx; pose proof INB as INBx; pose proof SHB as SHBx ].
    Ltac mp_tac := first [ eassumption | eapply (ah_mpres_trans H RT); [eassumption| eassumption] ].
    (* [comment removed for export] *)
    Ltac seg_side BR INB SHB :=
      first [ exact (bregs_uregs _ BR) | eassumption | exact UCTX | eapply pinb_sub; [exact INB| lia| lia] | eapply pshb_sub; [exact SHB| lia| lia] | lia
            | match goal with |- ?G => idtac "SEG-SIDE LEFT:" G; fail end ].
    (* [comment removed for export] *)
    Ltac leaf_pc E1 k := lazymatch type of E1 with _ = MS _ _ (Z_to_bv 64 ?x) _ _ _ _ => k x end.
    (* [comment removed for export] *)
    Ltac leaf_frame FRx :=
      lazymatch goal with
      | Hf : rw_cells _ _ (bv_unsigned spw) [C8 _; C8 _; C8 (Z_to_bv 64 9223372032559808512); C1 _; C1 _; CB 6 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _] |- _ =>
          pose proof (uframe_split8 _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hf) as FRx
      | Hf : rw_cells _ _ (bv_unsigned spw) [C8 _; C8 _; C4 _; C4 (Z_to_bv 64 (-2147483649)); C1 _; C1 _; CB 6 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _] |- _ =>
          pose proof (uframe_xsat _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hf) as FRx
      | Hf : rw_cells _ _ (bv_unsigned spw) _ |- _ => pose proof Hf as FRx
      | Hf : uframe _ spw _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => pose proof Hf as FRx
      end.

