    (* [comment removed for export] *)
    Lemma xend_fin : forall msF mo mc (r : rv) Fx pad (mw : word) (bc xc xn : Z) j6 f0 (q : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xfc694) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw pad mw (Z_to_bv 64 bc) (Z_to_bv 64 xc) (b8 xn) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> p + 2 <= q <= e -> -2^31 + 1 < bc <= 0 -> 0 <= xc < 2^31 -> 0 <= xn <= 1 ->
