    (* [comment removed for export] *)
    Ltac fail_leaf msF1 mo1 r1 Fx j6 f0 :=
      lazymatch goal with E1 : as_VIS _ _ msF1 = MS _ _ (Z_to_bv 64 ?pcv) _ _ _ _ |- _ =>
        eapply (failt_fin pcv msF1 mo1 _ r1 Fx fc _ _ _ _ _ _ j6 f0);
          [ first [ left; split; [reflexivity| breg1] | right; left; split; [reflexivity| split; breg1] | right; right; split; [reflexivity| split; breg1] ]
          | eassumption| mp_tac| exact E1| eassumption| eassumption| eassumption| (let FRx := fresh "FRx" in leaf_frame FRx; exact FRx)| bregs_tac| breg1| breg1| lia| lia| lia]
      end.
    Ltac fin_leaf msF1 mo1 r1 Fx pad mw xn j6 f0 :=
      lazymatch goal with E1 : as_VIS _ _ msF1 = MS _ _ _ _ _ _ _ |- _ =>
        let FRx := fresh "FRx" in leaf_frame FRx;
        eapply (fin_fin msF1 mo1 _ r1 Fx pad mw _ _ xn j6 f0);
          [eassumption| mp_tac| exact E1| eassumption| eassumption| exact FRx| bregs_tac| breg1| lia| lia| lia| lia| lia]
      end.

