    Lemma xlh_loopn : forall (n : nat) (q : Z) msF mo mc (r : rv) Fx pad (mw : word) (bc xc xn : Z) j6 f0,
      (Z.to_nat (e - q) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xfc5d0) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw pad mw (Z_to_bv 64 bc) (Z_to_bv 64 xc) (b8 xn) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 q -> ra7 r = Z_to_bv 64 xc ->
      ra1 r = Z_to_bv 64 9 -> ra2 r = Z_to_bv 64 (-2147483649) -> ra3 r = Z_to_bv 64 214748364 -> ra4 r = Z_to_bv 64 2 -> ra5 r = Z_to_bv 64 55 -> ra6 r = Z_to_bv 64 10 ->
      p + 2 <= q < e -> -2^31 + 1 < bc <= 0 -> 0 <= xc < 2^31 -> 0 <= xn <= 1 ->
      as_SR H POST (mkCfg msF mo).
Proof.
