    (* [comment removed for export] *)
    Ltac susp_leaf msF1 mo1 r1 Fx j6 f0 :=
      lazymatch goal with E1 : as_VIS _ _ msF1 = MS _ _ _ _ _ _ _ |- _ =>
        let FRx := fresh "FRx" in leaf_frame FRx;
        eapply (susp_fin msF1 mo1 _ r1 Fx _ _ _ _ _ _ j6 f0);
          [eassumption| mp_tac| exact E1| eassumption| eassumption| exact FRx| bregs_tac| breg1| breg1| breg1| lia]
      end.
    (* [comment removed for export] *)
    Ltac fin_leaf0 msF1 mo1 r1 Fx j6 f0 :=
      lazymatch goal with E1 : as_VIS _ _ msF1 = MS _ _ _ _ _ _ _ |- _ =>
        let FRx := fresh "FRx" in leaf_frame FRx;
        eapply (fin_fin msF1 mo1 _ r1 Fx _ _ _ _ _ j6 f0);
          [eassumption| mp_tac| exact E1| eassumption| eassumption| exact FRx| bregs_tac| breg1| lia| lia| lia| lia| lia]
      end.

    (* [comment removed for export] *)
    (* [comment removed for export] *)
    Lemma skh_loopn : forall (n : nat) (q : Z) msF mo mc (r : rv) Fx pad (mw : word) (bc : Z) j6 f0,
      (Z.to_nat (e - q) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xfc4cc) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw pad mw (Z_to_bv 64 bc) (Z_to_bv 64 0) (b8 0) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 e -> ra2 r = Z_to_bv 64 9 -> ra3 r = Z_to_bv 64 2 ->
      p + 3 <= q < e -> -2^31 + 1 < bc <= 0 ->
      as_SR H POST (mkCfg msF mo).
