      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw pad mw (Z_to_bv 64 bc) (Z_to_bv 64 0) (b8 0) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 (q + 1) -> ra2 r = mw -> ra7 r = Z_to_bv 64 bc ->
      ra3 r = Z_to_bv 64 9 -> ra4 r = Z_to_bv 64 1 -> ra5 r = Z_to_bv 64 (-2147483648) -> ra6 r = Z_to_bv 64 10 ->
      p + 2 <= q < e -> p - q <= bc <= 0 ->
      as_SR H POST (mkCfg msF mo).
Proof.
