    Lemma acd_fin : forall msF mo mc (r : rv) Fx pad j6 f0 (nd : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xfc298) fc None mc (seg_rom asegs) ->
