    Lemma cd_fin : forall msF mo mc (r : rv) Fx pad j6 f0,
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xfcd64) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw pad (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rra r = Z_to_bv 64 0xfc298 -> ra0 r = Z_to_bv 64 (p + 2) ->
      rs3 r = Z_to_bv 64 p -> rs1 r = Z_to_bv 64 (p + 2) -> rs5 r = Z_to_bv 64 (e + - p) ->
      p + 33 <= e ->
      as_SR H POST (mkCfg msF mo).
