    (* [comment removed for export] *)
    Ltac pushi_leaf msF1 mo1 r1 Fx j6 f0 :=
      lazymatch goal with E1 : as_VIS _ _ msF1 = MS _ _ _ _ _ _ _ |- _ =>
        let FRx := fresh "FRx" in leaf_frame FRx;
        eapply (bpushi_fin msF1 mo1 _ r1 Fx fc _ _ _ _ _ _ j6 f0);
          [eassumption| mp_tac| exact E1| eassumption| eassumption| eassumption| exact FRx| bregs_tac| breg1| lia]
      end.

    (* [comment removed for export] *)
    (* [comment removed for export] *)
    Lemma b90_fin : forall msF mo mc (r : rv) Fx pad j6 f0,
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xfc404) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw pad (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs3 r = Z_to_bv 64 p -> rs1 r = Z_to_bv 64 (p + 1) -> ra0 r = zxb (inb (p + 1)) -> p + 1 < e -> bv_unsigned (inb (p + 1)) <> 46 ->
      as_SR H POST (mkCfg msF mo).
